nlichtingendienst.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/1669065/de-man-die-twee-keer-doodging.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789403169613","key":{"isbn_13":"9789403169613"},"before":null,"after":{"work_id":2236,"title":"Het schot dat niemand raakte","isbn_13":"9789403169613","isbn_10":"9403169613","language":"nld","publisher":"Bezige Bij b.v., Uitgeverij De"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789403169613","key":{"edition_id":"@edition:9789403169613"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/1574152/het-schot-dat-niemand-raakte.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/1574152/het-schot-dat-niemand-raakte.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000571289_Het_schot_dat_niemand_raakte_0_0.jpg","checkedAt":"2026-10-31T22:49:57.581Z","sha256":"af65b3b463d8d186dfb5a84a19ccbd6c61aa150998af400b06bde4522fb2a474","bytes":277887,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789403169613","work_id":2236,"bound_author_id":391,"bound_title":"Het schot dat niemand raakte","bound_language":"nld","bound_isbn13":"9789403169613","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000571289_Het_schot_dat_niemand_raakte_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1574152/het-schot-dat-niemand-raakte.html"}},{"relation":"catalog_work_descriptions","ref":"description:2236:nl","key":{"work_id":2236,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00"