bba18586326fa0aa5a06e1e2d9dbdf719217e8ff7","bytes":652658,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":2519,"language":"nl","bound_author_id":1088,"text":"De broer van een overleden model gelooft niet dat haar val van een balkon zelfmoord was. Hij schakelt Cormoran Strike in, een privédetective die zelf met financiële en persoonlijke problemen kampt. Samen met zijn nieuwe assistente Robin onderzoekt Strike de wereld achter het publieke beeld van het slachtoffer. Hun eerste zaak brengt hen in kringen waar reputatie, geld en persoonlijke verhoudingen bepalen wat mensen bereid zijn te vertellen.","source_type":"official_publisher","source_name":"www.jkrowling.com","source_url":"https://www.jkrowling.com/about/","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022577240","key":{"isbn_13":"9789022577240"},"before":null,"after":{"work_id":2520,"title":"Zijderups","isbn_13":"9789022577240","isbn_10":"9022577244","language":"nld","publisher":"Meulenhoff Boekerij B.V."}},{"relation":"catalog_edition_metadata","ref":"metadata:9789022577240","key":{"edition_id":"@edition:9789022577240"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/179705/zijderups.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/179705/zijderups.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000031609_Zijderups_0_0.jpg","checkedAt":"2026-10-31T22:51:14.884Z","sha256":"e042cf1689ea8994c900f9d0ebc05dbb0aa3b2f1943d7b77a184f16e4ccb8df2","bytes":113997,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"edition_id":"@edition:9789022577240","work_id":2520,"bound_author_id":1088,"bound_title":"Zijderups","bound_language":"nld","bound_isbn13":"9789022577240","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000031609_Zijderups_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/179705/zijderups.html"}},{"relation":"catalog_work_descriptions","ref":"description:2520:nl","key":{"work_id":2520,"language":"nl"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/179705/zijderups.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://metadata.isbn.nl/179705/zijderups.html","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000031609_Zijderups_0_0.jpg","checkedAt":"2026-10-31T22:51:14.884Z","sha256":"e042cf1689ea8994c900f9d0ebc05dbb0aa3b2f1943d7b77a184f16e4ccb8df2","bytes":113997,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":2520,"language":"nl","bound_author_id":1088,"text":"Wanneer schrijver Owen Quine verdwijnt, vraagt zijn vrouw Cormoran Strike om hulp. De detective ontdekt een verband met een manuscript waarin bekenden van de auteur zich onaangenaam herkennen. De zaak krijgt een ernstiger karakter wanneer Quine dood wordt gevonden. Samen met Robin probeert Strike de belangen en vijandigheden rond de tekst te doorgronden, voordat de dader opnieuw kan handelen. De Londense literaire wereld vormt het decor van hun tweede onderzoek.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/179705/zijderups.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789022566459","key":{"isbn_13":"9789022566459"},"before":null,"after":{"work_id":1389,"title":"Het teken van Athena","isbn_13":"9789022566459","isbn_1