he/0000610008_Het_teken_van_Athena_0_0.jpg","checkedAt":"2026-10-31T23:12:16.974Z","sha256":"9ecc0687b8645701b5bd4ead6af973b7dd43a564d162aebe63d2cb3835d3c0cb","bytes":495665,"fact":"Manual title/author/exact edition cover binding, readable published front"}],"work_id":1389,"language":"nl","bound_author_id":111,"text":"Annabeth staat voor een opdracht die nauw verbonden is met haar moeder Athena. Tegelijk proberen Griekse en Romeinse halfgoden samen te werken, hoewel hun wederzijdse wantrouwen dat voortdurend bemoeilijkt. Percy en zijn reisgenoten moeten een groter gevaar het hoofd bieden. In het derde Helden van Olympus-boek krijgt Annabeths eigen zoektocht een centrale plaats binnen een onderneming waarvoor de groep elkaar nodig heeft.","source_type":"official_catalog","source_name":"Bureau ISBN","source_url":"https://metadata.isbn.nl/2083422/het-teken-van-athena.html","provenance":"original_source_reviewed_summary"}},{"relation":"editions","ref":"edition:9789000342426","key":{"isbn_13":"9789000342426"},"before":null,"after":{"work_id":1406,"title":"Het huis van Hades","isbn_13":"9789000342426","isbn_10":"9000342422","language":"nld","publisher":"Uitgeverij Unieboek | Het Spectrum"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789000342426","key":{"edition_id":"@edition:9789000342426"},"before":null,"after":{"review_status":"approved","reviewed_at":"2026-11-01T00:00:00+01:00","review_batch":"nl-cohort003-02-20261101","evidence":[{"url":"https://metadata.isbn.nl/2094506/het-huis-van-hades.html","checkedAt":"2026-11-01","fact":"Exact edition/title/author/ISBN/format/cover source, not title-based language inference"},{"url":"https://www.bibliotheek.nl/catalogus/titel.429370679.html/het-huis-van-hades/","checkedAt":"2026-11-01","fact":"Exact-edition language decision"},{"url":"https://metadata.isbn.nl/ie_fcache/0000610014_Het_huis_van_Hades_0_0.jpg","checkedAt":"2026-10-31T23:12:18.996Z","sha256":"6070d4a84185e181a4eb87c6faa57bb8a89d821d91de5ac893f069167920